stappen.script:
// De rijen uit het databaseblok (een lege lijst als er niets kwam).
var rijen = Haal_Orders.result || [];
// Eén regel tekst per order.
var regels = rijen.map(function (r) {
  return r.datum + ' ' + r.ordernummer + ' ' + r.klant + ' (' + r.leverwijze + ', ' + r.plaats + ')';
});
// <br> is een nieuwe regel in de mail.
return { aantal: rijen.length, tekst: regels.join('<br>') };
